function main(input) {
  const want = input.amount >= 100000 ? "部長" : "課長";
  const hit = (input.items || []).find(r => r.data && r.data.level === want);
  if (!hit) throw new Error("役職「" + want + "」の承認者が承認者テーブルにいません");
  return { name: hit.data.name, level: want };
}

