function main(input) {
  const m = {};
  for (const it of input.items) {
    const d = it.data;
    const rep = d.rep ?? '';
    if (!m[rep]) m[rep] = { rep: rep, visits: 0, prospect: 0 };
    m[rep].visits += Number(d.visits || 0);
    m[rep].prospect += Number(d.prospect || 0);
  }
  const rows = Object.values(m).map(r => ({ week_start: input.week_start, rep: r.rep, visits: r.visits, prospect: r.prospect }));
  const lines = rows.map(r => r.rep + ': 訪問 ' + r.visits + ' 件、見込み額 ' + r.prospect);
  return { rows: rows, summary: lines.join('\n'), count: input.items.length };
}

