function main(input) {
  const items = input.items || [];
  const selected = [];
  for (const it of items) {
    const d = it.data || {};
    if (!d.code || d.qty == null || d.reorder_point == null) continue;
    if (Number(d.qty) < Number(d.reorder_point)) {
      selected.push({ code: String(d.code), name: String(d.name ?? ''), order_qty: Number(d.reorder_qty ?? 0) });
    }
  }
  const esc = (v) => { const s = String(v); return /[",\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };
  const lines = ['品番,品名,発注数', ...selected.map(r => [r.code, r.name, r.order_qty].map(esc).join(','))];
  return { selected: selected, csv: lines.join('\r\n') + '\r\n' };
}

