    lines.push("| " + (d.code ?? "") + " | " + (d.borrower ?? "") + " | " + (d.due_on ?? "") + " |");
  }
  if (items.length === 0) lines.push("", "延滞はありません。");
  return { text: lines.join("\n") };
}

function main(input) {
  const today = input.today;
  const items = (input.items || []).map(r => ({
    code: (r.data && r.data.code) || '',
    borrower: (r.data && r.data.borrower) || '',
    due: (r.data && r.data.due_on) || ''
  })).sort((a, b) => a.due < b.due ? -1 : a.due > b.due ? 1 : 0);
  const lines = [];
  lines.push('# 延滞一覧 ' + today);
  lines.push('');
  lines.push('返却予定日を過ぎて未返却の備品: ' + items.length + ' 件');
  lines.push('');
  if (items.length === 0) {
    lines.push('延滞はありません。');
  } else {
    lines.push('| 管理番号 | 借りた人 | 返却予定日 |');
    lines.push('|---|---|---|');
    for (const r of items) {
      lines.push('| ' + r.code + ' | ' + r.borrower + ' | ' + r.due + ' |');
    }
  }
  return { text: lines.join('\n') + '\n' };
}

function main(input) {
