function main(input) {
  var q = String(input.question || '').replace(/\s+/g, '');
  function grams(s) {
    var out = {};
    for (var i = 0; i < s.length - 1; i++) { out[s.substr(i, 2)] = true; }
    return Object.keys(out);
  }
  var qg = grams(q);
  var best = null;
  var bestScore = 0;
  var items = input.items || [];
  for (var i = 0; i < items.length; i++) {
    var fq = String(items[i].data.question || '').replace(/\s+/g, '');
    if (!fq) continue;
    var fg = grams(fq);
    var shared = 0;
    for (var j = 0; j < qg.length; j++) { if (fg.indexOf(qg[j]) >= 0) shared++; }
    var ratio = fg.length ? shared / fg.length : 0;
    if (shared >= 2 && ratio >= 0.5 && shared > bestScore) { bestScore = shared; best = items[i]; }
  }
  return { items: best ? [best] : [] };
}

prompt.$template:
質問: {question}

よくある質問（番号 {faq_no}）:
質問文: {faq_question}
回答: {faq_answer}

上記の回答をもとに、質問に対する答えの文章を作成してください。

source.inline:
function main(input) {
  const norm = (s) => String(s ?? '').replace(/\s+/g, '');
  const bigrams = (s) => { const set = new Set(); for (let i = 0; i < s.length - 1; i++) set.add(s.slice(i, i + 2)); return set; };
  const q = norm(input.question);
  const qb = bigrams(q);
  let best = null;
  let bestScore = 0;
  for (const it of (input.faqs ?? [])) {
    const d = it.data ?? {};
    const fb = bigrams(norm(d.question));
    if (fb.size === 0) continue;
    let common = 0;
    for (const b of fb) if (qb.has(b)) common++;
    const score = common / fb.size;
    if (score > bestScore) { bestScore = score; best = d; }
  }
  if (best && bestScore >= 0.5) {
    return { hit: true, faq_no: String(best.faq_no ?? ''), faq_question: String(best.question ?? ''), faq_answer: String(best.answer ?? ''), score: bestScore };
  }
  return { hit: false, faq_no: '', faq_question: '', faq_answer: '', score: bestScore };
}

