function main(input) {
  if (!String(input.name).toLowerCase().endsWith('.csv')) return { rows: [] };
  const t = String(input.text).replace(/^\uFEFF/, '');
  const lines = t.split(/\r?\n/).filter(l => l.trim() !== '');
  const rows = [];
  for (let i = 1; i < lines.length; i++) {
    const c = lines[i].split(',').map(s => s.trim());
    rows.push({ assignee: c[0] || '', task: c[1] || '', due_on: c[2] || null });
  }
  return { rows: rows };
}
